parameters.jsCode:
const input = $('Parse BA Input').first().json;
const classified = $json.message?.content ? JSON.parse($json.message.content) : {};

const projectName = (input.projectName && input.projectName.trim()) 
  ? input.projectName.trim() 
  : (classified.proposedProjectName || 'architecture-project');

const slugify = (s) => String(s || '')
  .toLowerCase()
  .trim()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .replace(/--+/g, '-');

const projectSlug = input.projectSlug || slugify(projectName) || 'architecture-project';

// Generate job ID
const pad = (n) => String(n).padStart(2, '0');
const d = new Date();
const ts = d.getUTCFullYear() + pad(d.getUTCMonth() + 1) + pad(d.getUTCDate()) + '-' + pad(d.getUTCHours()) + pad(d.getUTCMinutes()) + pad(d.getUTCSeconds());

const fnv1a = (str) => {
  const s = String(str ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { hash ^= s.charCodeAt(i); hash = (hash * 0x01000193) >>> 0; }
  return ('0000000' + hash.toString(16)).slice(-8);
};

const ackJobId = 'job_' + ts + '_' + fnv1a(projectSlug + ':' + input.requirements);

return [{
  json: {
    requirements: input.requirements,
    projectName,
    projectSlug,
    intent: classified.intent || 'create_project',
    confidence: classified.confidence ?? null,
    comments: input.comments,
    ackJobId,
    source: 'business-analysis'
  }
}];

const chatInput = $('Parse Chat Input').first().json;
let extracted = {};

// Parse LLM response
try {
  const content = $json.message?.content || '{}';
  // Clean up potential markdown code blocks
  const cleaned = content.replace(/```json\n?|```\n?/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  // Default to business-analysis if parsing fails
  extracted = {
    intent: 'business-analysis',
    projectSlug: null,
    requirements: chatInput.chatInput
  };
}

// Slugify helper
const slugify = (s) => String(s || '')
  .toLowerCase()
  .trim()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .replace(/--+/g, '-');

// Generate projectSlug if not provided
let projectSlug = extracted.projectSlug;
if (!projectSlug && extracted.requirements) {
  // Extract first few words for slug
  const words = String(extracted.requirements).split(/\s+/).slice(0, 3).join(' ');
  projectSlug = slugify(words) || 'chat-project';
}
projectSlug = projectSlug || 'chat-project';

// Generate job ID
const pad = (n) => String(n).padStart(2, '0');
const d = new Date();
const ts = d.getUTCFullYear() + pad(d.getUTCMonth() + 1) + pad(d.getUTCDate()) + '-' + pad(d.getUTCHours()) + pad(d.getUTCMinutes()) + pad(d.getUTCSeconds());

const fnv1a = (str) => {
  const s = String(str ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { hash ^= s.charCodeAt(i); hash = (hash * 0x01000193) >>> 0; }
  return ('0000000' + hash.toString(16)).slice(-8);
};

const ackJobId = 'job_' + ts + '_' + fnv1a(projectSlug + ':' + chatInput.chatInput);

return [{
  json: {
    sessionId: chatInput.sessionId,
    chatInput: chatInput.chatInput,
    intent: extracted.intent || 'business-analysis',
    projectSlug,
    projectName: projectSlug.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase()),
    requirements: extracted.requirements || (extracted.intent === 'business-analysis' ? chatInput.chatInput : null),
    ackJobId,
    source: 'chat'
  }
}];

// Format response for Open WebUI chat pipe
const processData = $('Process Chat LLM Response').first().json;
const baResult = $json || {};

const output = `Started Business Analysis for **${processData.projectSlug}** (job: ${processData.ackJobId}).\n\nBRD generation is now in progress. You can:\n- Check status with: "status ${processData.projectSlug}"\n- Continue to architecture: "generate architecture for ${processData.projectSlug}"`;

return [{ json: { output } }];

// Format response for async workflows
const processData = $('Process Chat LLM Response').first().json;

const workflowNames = {
  'architecture': 'Architecture',
  'solution-architecture': 'Solution Architecture',
  'risk-assessment': 'Risk Assessment',
  'test-strategy': 'Test Strategy',
  'project-management': 'Project Management',
  'software-delivery': 'Software Delivery'
};

const workflowName = workflowNames[processData.intent] || processData.intent;

const output = `Started **${workflowName}** workflow for **${processData.projectSlug}** (job: ${processData.ackJobId}).\n\nThis workflow is running in the background. Check status with: "status ${processData.projectSlug}"`;

return [{ json: { output } }];

// Status check or unknown intent
const processData = $('Process Chat LLM Response').first().json;

let output;
if (processData.intent === 'status-check') {
  output = `Status check for **${processData.projectSlug || 'project'}** is not yet implemented.\n\nPlease check the n8n workflow executions or database directly for now.`;
} else {
  output = `I understood your request but couldn't determine the specific action.\n\nDetected intent: ${processData.intent}\nProject: ${processData.projectSlug || 'not specified'}\n\nTry being more specific, or type "help" for available commands.`;
}

return [{ json: { output } }];

